update legal_version set status = 'ARCHIVED', archived_at = now(), updated_at = now()
    where doc_type = 'cookies' and status = 'CURRENT' and (major, minor, patch) < (1, 0, 0);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies,
                           change_summary, created_at, created_by, updated_at, archived_at)
select '1977dba1-3278-5a12-aa73-0aac1f3fe08e'::uuid, 'cookies', '1.0', 1, 0, 0, '2026-12-01'::date, 'CURRENT', true,
       '{"en": "# Cookie Notice\n\n## What cookies are\n\nCookies are small files that a website stores on your device. We also use similar technologies that work in the same way: local storage and session storage in your browser, pixels (tiny images that report that a page or email was opened), and software development kits (SDKs) inside our mobile apps. In this notice, \"cookies\" means all of them.\n\n## How we use them\n\nWe group cookies into four categories. Strictly necessary cookies are always on because the Services cannot work without them. You choose the others.\n\n- **Strictly necessary.** Sign you in, keep your cart, remember your cookie choices, protect payments from fraud and keep the Services secure. You cannot turn these off in our banner. You can block them in your browser, but then parts of the Services, such as sign-in, the cart and checkout, will not work.\n- **Functional.** Remember choices such as your language, region and delivery ZIP code, so we can show delivery dates and prices that match your place.\n- **Analytics.** Help us understand how the Services are used and how fast they run, so that we can fix problems and improve them. We use de-identified measures where we can. A pre-order campaign touch is stored for 30 days only if you allow analytics or advertising.\n- **Advertising.** Help us measure whether our ads work and show you AfroTransact ads on other sites and platforms. These are off until you allow them.\n\n## Your choices\n\nThe first time you visit, a banner asks for your choices. You can accept all, reject all, or choose by category. Your choice is saved for 12 months in a strictly necessary cookie (`at_consent`). You can change it at any time from \"Cookie preferences\" in the footer of every page. If you clear your cookies, we will ask again.\n\nYou can also block or delete cookies in your browser settings. Mobile operating systems let you reset or limit your advertising identifier. These controls are separate from ours, and a blocked cookie cannot remember that you blocked it.\n\n## Global Privacy Control\n\nWe honour the Global Privacy Control (GPC) browser signal as a valid request to opt out of advertising cookies and of sale and sharing of your personal information. If your browser sends GPC, advertising cookies stay off and the \"Do not sell or share\" choice is switched on for that browser without you having to do anything else. If you are signed in, we also apply the choice to your account. We do not respond to the older \"Do Not Track\" header, because there is no agreed standard for it. [[LEGAL: Q27 confirm the GPC behaviour for signed-in accounts and for browsers that later drop the signal]]\n\n## Cookies we use\n\nThe table below is generated from the same configuration as the cookie banner, so it is the current list. At the time of writing it contains:\n\n| Name | Provider | What it does | How long | Category |\n|---|---|---|---|---|\n| `at_session` | AfroTransact | Keeps you signed in | Session | Strictly necessary |\n| `at_cart` | AfroTransact | Remembers your cart | 30 days | Strictly necessary |\n| `at_consent` | AfroTransact | Remembers your cookie choices and \"Do not sell or share\" | 12 months | Strictly necessary |\n| `__stripe_mid` | Stripe | Fraud prevention during payment | 1 year | Strictly necessary |\n| `at_locale` | AfroTransact | Language and region | 1 year | Functional |\n| `at_zip` | AfroTransact | Delivery ZIP for dates and prices | 90 days | Functional |\n| `_at_metrics` | AfroTransact | De-identified page performance | 13 months | Analytics |\n| `at_attr` | AfroTransact | Which campaign link brought you to a pre-order (last touch) | 30 days | Analytics |\n| `_gcl_au` | Google Ads | Measure ad conversions | 90 days | Advertising |\n| `_fbp` | Meta | Show ads on Meta platforms | 90 days | Advertising |\n\nStripe may also set other cookies and use device signals on payment pages and in the Stripe-hosted payment fields. We list the ones that can persist on your device; Stripe describes its own technologies in its privacy policy and cookie information. [[LEGAL: Q27 confirm the final cookie list before launch, including Stripe''s payment-page cookies, any error-monitoring (Sentry) storage, Google Maps address-field storage and any SDK identifiers in the mobile apps, and whether each is strictly necessary]]\n\n## Mobile apps\n\nOur apps do not use browser cookies. They use local storage on your device and SDKs for sign-in, push notifications (Firebase Cloud Messaging on Android, Apple Push Notification service on iPhone), crash reporting and payments. Push notifications are controlled in your device settings and in Your account > Notifications.\n\n## Third parties and sharing\n\nIf you allow advertising cookies, the advertising providers named in the table receive information such as a cookie identifier, the pages you view and the actions you take (for example, adding to the cart or buying). Under some state laws, this may count as \"sharing\" for cross-context behavioural advertising or as a \"sale\". You can opt out through the footer link, a GPC signal, or Your Privacy Choices. [[LEGAL: Q11 and Q27 confirm sale/share characterisation and whether purchase events are sent to advertisers]]\n\n## Changes and contact\n\nWe update this notice when we add or remove a cookie, and we ask again for your consent if a change needs it. Questions: {privacy}. {address}."}'::jsonb, 'First customer-facing version for launch. Table now includes the consent and campaign cookies and states how Global Privacy Control is treated.', now(), 'legal-loader', now(), null
 where not exists (select 1 from legal_version where doc_type = 'cookies' and (major, minor, patch) >= (1, 0, 0));
update legal_version set effective_date = '2026-12-01'::date, draft_banner = true,
