-- privacy-choices 1.0 (effective 2026-12-01; locales: en; draft banner on)
delete from legal_version where doc_type = 'privacy-choices' and created_by = 'seed'
    and exists (select 1 from legal_version c where c.doc_type = 'privacy-choices' and c.status = 'CURRENT'
                and c.created_by = 'seed' and c.updated_at = c.created_at and (c.major, c.minor, c.patch) > (1, 0, 0));
update legal_version set status = 'ARCHIVED', archived_at = now(), updated_at = now()
    where doc_type = 'privacy-choices' and status = 'CURRENT' and (major, minor, patch) < (1, 0, 0);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies,
                           change_summary, created_at, created_by, updated_at, archived_at)
select 'c4f00b8a-5a50-5690-baf9-da39f5412fc1'::uuid, 'privacy-choices', '1.0', 1, 0, 0, '2026-12-01'::date, 'CURRENT', true,
       '{"en": "# Your Privacy Choices\n\n## Your rights\n\nThis page explains the choices you have over your personal information and how to use them. It supports the Privacy Notice and the Cookie Notice. We offer these choices to everyone in the United States, whether or not your state law requires it. [[LEGAL: Q11 confirm whether to offer the rights to all US customers or only to residents of states with a law, and the applicable thresholds]]\n\nLaws that give these rights include the California Consumer Privacy Act as amended by the California Privacy Rights Act (CCPA/CPRA), the Virginia Consumer Data Protection Act (VCDPA), the Colorado Privacy Act (CPA), the Connecticut Data Privacy Act (CTDPA), the Utah Consumer Privacy Act, the Texas Data Privacy and Security Act, the Oregon Consumer Privacy Act and similar laws in other states. [[LEGAL: Q11 list of states in force at launch and in the launch markets]]\n\nDepending on your state, you can:\n\n- **Know and access.** Ask what personal information we collected about you, where it came from, why we use it, who we share it with, and get a copy of it.\n- **Correct.** Ask us to fix inaccurate information.\n- **Delete.** Ask us to delete the personal information we collected from you.\n- **Port.** Get a copy of your data in a portable, usable format.\n- **Opt out of sale and sharing.** Tell us not to sell your personal information or share it for cross-context behavioural advertising.\n- **Opt out of targeted advertising and profiling.** Tell us not to use your information for targeted advertising, or for profiling that produces legal or similarly significant effects.\n- **Limit sensitive information.** Ask us to limit the use of sensitive personal information to what is needed to give you the Services.\n- **Appeal** a decision on your request.\n- **No retaliation.** We will not charge you different prices, deny you service or give you worse service for using these rights. Offering a program that depends on your data (for example Plus membership) is not retaliation, but we will tell you if deleting data means we cannot provide a benefit.\n\n## Do Not Sell or Share My Personal Information\n\nWe do not sell personal information for money. Some advertising and measurement features may count as a \"sale\" or \"sharing\" under some state laws. To opt out, you can:\n\n1. Use the **Do not sell or share my personal information** link in the footer (or the toggle in Cookie preferences), or the privacy request form on this page.\n2. Turn on **Global Privacy Control** in your browser or a browser extension. We treat GPC as a valid opt-out request for that browser, and we also apply it to your account when you are signed in.\n3. Email {privacy}.\n\nOpting out turns off advertising cookies and stops us sending your information to advertising providers for those purposes. It does not stop the cookies and sharing needed to run the Services (for example fraud prevention at checkout, delivery to the seller and driver, and email delivery).\n\nWe do not knowingly sell or share the personal information of anyone under 16. [[LEGAL: Q10 and Q11 confirm]]\n\n## Global Privacy Control\n\nIf your browser sends the Global Privacy Control signal, we honour it without asking you to take any further step. We apply it to the browser you are using, and to your account if you are signed in. We do not need you to confirm it. If GPC conflicts with a setting you have saved in your account, we apply the more privacy-protective option and tell you how to change it.\n\n## Marketing choices\n\nYou can stop marketing messages at any time:\n\n- **Email:** use the unsubscribe link in any marketing email. It works in one click.\n- **SMS:** reply STOP to any text. WhatsApp marketing has its own opt-in and opt-out; you can reply STOP or change it in Your account > Notifications.\n- **Push:** change the setting on your device or in Your account > Notifications.\n\nWe will still send messages about your orders, deliveries, bookings, payments and security while your account is open. Details are in the SMS and Notification Terms.\n\n## How to make a request\n\nChoose one:\n\n- Use the privacy request form on this page [[LEGAL: Q11 confirm that the form is live at launch]], or contact us at {privacy}.\n- Email {privacy}.\n- Call {phone} [[LEGAL: Q11 whether a toll-free number is required for the launch states]].\n\nTell us your name, the email address on your account, your state, and what you want us to do. If you want to opt out of sale and sharing, you do not need to give anything more than a way to recognise your browser or account.\n\n## How we verify you\n\nFor requests to know, access, correct, delete or port data, we need to be sure that the request is from you or from someone you authorised. We send a confirmation link to the email address on your account. For deletion we also ask you to sign in. For sensitive or high-risk requests we may ask for a few more details that match what we already hold. We will not ask for more information than we need and we will use it only to check your identity. We do not need to verify opt-outs.\n\n## Authorised agents\n\nYou can ask someone else to make a request for you. They must give us your signed permission (or a power of attorney), and we may check with you directly that you gave it. Opt-out requests sent by an agent through a GPC browser extension are treated as yours.\n\n## How and when we respond\n\nWe confirm that we received your request within 10 business days and respond within 45 days of receiving it. If we need more time, we may extend that once by another 45 days and will tell you why. We respond by email or in your account. We will not charge a fee unless a request is clearly excessive or repeated; then we will tell you before we charge or refuse. [[LEGAL: Q11 confirm response times for each state, including 15 business days for opt-outs under CCPA and the number of free requests a year]]\n\nIf we cannot do what you ask, for example because the law requires us to keep a record, we will say so and explain why. Deleting your data means closing your account. We keep the records we are required to keep, such as tax and accounting records for 7 years, and records of your requests and opt-outs so that we can honour them.\n\nDeleting your account also ends your store credit, membership benefits and referral rewards. If you have a store credit balance, use it first; credit cannot be converted to cash. See the Store Credit Terms.\n\n## Appeals\n\nIf we decline or only partly complete your request, you can appeal. Reply to our response with the word \"Appeal\", or email {privacy} with the subject \"Privacy appeal\". A person who was not involved in the first decision will review it, and we will answer in writing within 60 days and explain the reasons. If the appeal is denied, you can raise a complaint with your state attorney general, and we will give you the contact details. [[LEGAL: Q11 appeal timelines by state (45 to 60 days) and the attorney-general contact line required in the response]]\n\n## Categories of information and who receives it\n\nIn the 12 months before this notice we collected the categories of personal information in the table in the Privacy Notice. We disclosed identifiers, commercial information, payment tokens, delivery information, location information, device and usage information and messages to the categories of recipients listed in the \"Who we share it with\" section of the Privacy Notice, for the business purposes there. Advertising providers received only identifiers, device and usage information, and purchase events, and only for people who had allowed advertising cookies. We do not sell or share SMS or WhatsApp opt-in data or mobile numbers. [[LEGAL: Q11 replace with a precise, audited statement by category and recipient for the first 12 months after launch]]\n\n## Financial incentives\n\nOur referral rewards, gift cards and Plus membership are not a payment for your personal information. Some use information you give us, such as your email address, to work. If you opt out of sale or sharing, you can still take part. [[LEGAL: Q11 confirm no notice of financial incentive is required, or add one]]\n\n## Contact\n\nPrivacy: {privacy}. Address: {address}. Phone: {phone}. Accessibility help: {accessibility}."}'::jsonb, 'First customer-facing version for launch. Covers the US state privacy laws, opt-outs, Global Privacy Control and how to make and appeal a request.', now(), 'legal-loader', now(), null
 where not exists (select 1 from legal_version where doc_type = 'privacy-choices' and (major, minor, patch) >= (1, 0, 0));
