-- returns 1.0 (effective 2026-12-01; locales: en; draft banner on)
delete from legal_version where doc_type = 'returns' and created_by = 'seed'
    and exists (select 1 from legal_version c where c.doc_type = 'returns' and c.status = 'CURRENT'
                and c.created_by = 'seed' and c.updated_at = c.created_at and (c.major, c.minor, c.patch) > (1, 0, 0));
